<?php require_once '../includes/functions.php';if(logged_in())redirect('user/dashboard.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$pdo->prepare('SELECT * FROM users WHERE email=? AND status="active"');$s->execute([strtolower(trim($_POST['email']))]);$u=$s->fetch();if($u&&password_verify($_POST['password'],$u['password'])){session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];redirect($u['role']==='admin'?'admin/index.php':'user/dashboard.php');}$error='Incorrect email or password.';}$page_title='Login';require '../includes/header.php';?><section class="auth-layout"><div class="auth-photo" style="background-image:url('https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?w=1200')"><h1>Welcome<br>back.</h1><p>Your next Bangladesh adventure starts here.</p></div><div class="auth-panel"><h2>Login</h2><p class="muted">Access your travel dashboard.</p><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><form method="post" class="form-card"><?=csrf_field()?><label>Email Address<input type="email" name="email" required></label><label>Password<div class="password-field"><input id="login-password" type="password" name="password" required autocomplete="current-password"><button class="password-toggle" type="button" aria-controls="login-password" aria-label="Show password" aria-pressed="false">Show</button></div></label><button class="btn btn-primary btn-block">Login</button></form><p class="center">Don't have an account? <a href="register.php">Register</a></p></div></section><?php require '../includes/footer.php';?>
